"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Activity, ArrowRight, Building2, CalendarClock, CheckCircle2, ChevronRight,
  CircleAlert, Eye, FileText, Globe2, GraduationCap, LayoutDashboard, Link2,
  LoaderCircle, Pencil, Plus, ReceiptIndianRupee, RefreshCw, ShieldCheck,
  Trash2, UsersRound, WalletCards, X,
} from "lucide-react";
import type { PortalRole } from "@/lib/roles";
import { visibleModules } from "@/lib/roles";

type Row = Record<string, unknown>;
type ModuleId = "students" | "parents" | "teachers" | "classes" | "timetable";
type Field = { key: string; label: string; type?: "text" | "number" | "textarea" };
type Module = { id: ModuleId; label: string; endpoint: string; description: string; fields: Field[]; columns: Array<[string, string]>; create: string; icon: typeof UsersRound; tone: string };
type Dashboard = { total_students?: number; total_staff?: number; total_sections?: number; pending_leave_requests?: number; metrics?: Record<string, number>; today_attendance?: { attendance_pct?: number; present?: number; marked?: number }; fees?: { collection_pct?: number; total_paid?: number }; recent_announcements?: Array<{ id: string; title?: string; priority?: string }> };
type FeeState = { structures: Row[]; invoices: Row[]; payments: Row[]; requests: Row[]; concessions: Row[]; categories: Row[]; years: Row[]; grades: Row[]; sections: Row[]; config: Row };

const modules: Module[] = [
  { id: "students", label: "Students & Parents", endpoint: "students?page=1&page_size=50", description: "Admissions, learner profiles, and parent accounts from the live SchoolDesk backend.", create: "students", fields: [], columns: [["student_id_number", "Student ID"], ["first_name", "Student"], ["current_section", "Class / section"], ["status", "Status"]], icon: UsersRound, tone: "blue" },
  { id: "parents", label: "Parents", endpoint: "users?role=parent&page=1&page_size=50", description: "Manage parent portal accounts and family details.", create: "users", fields: [{ key: "name", label: "Parent name" }, { key: "username", label: "Username" }, { key: "email", label: "Email" }, { key: "phone", label: "Phone" }, { key: "password", label: "Temporary password" }], columns: [["name", "Parent"], ["username", "Username"], ["email", "Email"], ["phone", "Phone"]], icon: UsersRound, tone: "gold" },
  { id: "teachers", label: "Teachers", endpoint: "staff?page=1&page_size=50", description: "Teacher and coordinator profiles use the exact staff account contract used by the Flutter app.", create: "staff", fields: [], columns: [["staff_code", "Employee ID"], ["first_name", "Teacher"], ["designation", "Designation"], ["phone", "Phone"]], icon: GraduationCap, tone: "green" },
  { id: "classes", label: "Classes", endpoint: "principal/classes", description: "Set up class sections, teaching assignments, and capacity.", create: "principal/classes", fields: [{ key: "academic_year_id", label: "Academic year ID" }, { key: "grade_name", label: "Grade name" }, { key: "grade_number", label: "Grade number", type: "number" }, { key: "section_name", label: "Section" }, { key: "capacity", label: "Capacity", type: "number" }], columns: [["grade_name", "Class"], ["section_name", "Section"], ["student_count", "Students"], ["capacity", "Capacity"]], icon: Building2, tone: "violet" },
  { id: "timetable", label: "Timetable", endpoint: "timetable/slots", description: "Create and update timetable slots from the same academic data as the mobile app.", create: "timetable/slots", fields: [{ key: "section_id", label: "Section ID" }, { key: "academic_year_id", label: "Academic year ID" }, { key: "day_of_week", label: "Day (1–7)", type: "number" }, { key: "start_time", label: "Start time" }, { key: "end_time", label: "End time" }, { key: "subject_id", label: "Subject ID" }], columns: [["day_of_week", "Day"], ["start_time", "Starts"], ["end_time", "Ends"], ["subject_name", "Subject"]], icon: CalendarClock, tone: "teal" },
];

const navMeta: Record<string, { icon: typeof LayoutDashboard; label: string }> = { overview: { icon: LayoutDashboard, label: "Overview" }, students: { icon: UsersRound, label: "Students & Parents" }, parents: { icon: UsersRound, label: "Parents" }, teachers: { icon: GraduationCap, label: "Teachers" }, classes: { icon: Building2, label: "Classes" }, timetable: { icon: CalendarClock, label: "Timetable" }, fees: { icon: WalletCards, label: "Fees" }, website: { icon: Globe2, label: "Public Website" } };
const emptyFees: FeeState = { structures: [], invoices: [], payments: [], requests: [], concessions: [], categories: [], years: [], grades: [], sections: [], config: {} };

async function api(path: string, init: RequestInit = {}) {
  const response = await fetch(`/api/backend/${path}`, { ...init, headers: { ...(init.body instanceof FormData ? {} : { "Content-Type": "application/json" }), ...(init.headers ?? {}) } });
  const body = await response.json().catch(() => ({}));
  if (!response.ok || body.success === false) throw new Error(body.error || "Request failed");
  return body.data;
}
function rowsFrom(data: unknown): Row[] { if (Array.isArray(data)) return data as Row[]; if (data && typeof data === "object") { const row = data as Row; for (const key of ["data", "classes", "slots", "users", "staff", "students"]) if (Array.isArray(row[key])) return row[key] as Row[]; } return []; }
function stringValue(value: unknown) { return value === null || value === undefined || value === "" ? "" : String(value); }
function nested(row: Row, key: string) { const value = row[key]; return value && typeof value === "object" && !Array.isArray(value) ? value as Row : {}; }
function rowText(row: Row, key: string) {
  if (key === "current_section") { const section = nested(row, "current_section"); const grade = nested(section, "grade"); return [stringValue(grade.grade_name ?? grade.name), stringValue(section.section_name ?? section.name)].filter(Boolean).join(" · ") || "—"; }
  if (key === "grade_name") return stringValue(nested(row, "grade").grade_name ?? nested(row, "grade").name ?? row[key]) || "—";
  if (key === "subject_name") return stringValue(nested(row, "subject").subject_name ?? nested(row, "subject").name ?? row[key]) || "—";
  return stringValue(row[key]) || "—";
}
function money(value: unknown) { return new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(Number(value) || 0); }
function splitName(name: string) { const pieces = name.trim().split(/\s+/).filter(Boolean); return { first_name: pieces.shift() || "", last_name: pieces.join(" ") }; }
function displayName(row: Row) { return [stringValue(row.first_name), stringValue(row.last_name)].filter(Boolean).join(" ") || stringValue(row.name) || "—"; }

function Toast({ message, onClose }: { message: string; onClose: () => void }) { useEffect(() => { const timer = window.setTimeout(onClose, 4500); return () => window.clearTimeout(timer); }, [onClose]); return <div className="ops-toast" role="status"><CheckCircle2 size={18}/><span>{message}</span><button onClick={onClose} aria-label="Dismiss notification"><X size={15}/></button></div>; }
function Dialog({ kicker, title, children, onClose }: { kicker: string; title: string; children: React.ReactNode; onClose: () => void }) { return <div className="dialog-backdrop" role="presentation"><section className="dialog ops-dialog" role="dialog" aria-modal="true" aria-labelledby="record-dialog-title"><button className="icon-button" style={{ float: "right" }} onClick={onClose} aria-label="Close"><X size={16}/></button><p className="dialog-kicker">{kicker}</p><h3 id="record-dialog-title">{title}</h3>{children}</section></div>; }
function FormActions({ saving, onClose, label = "Save changes" }: { saving: boolean; onClose: () => void; label?: string }) { return <div className="dialog-footer"><button className="secondary-button" type="button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={saving}>{saving ? <><LoaderCircle className="spin" size={16}/> Saving</> : label}</button></div>; }

function StudentDialog({ row, readOnly, onClose, onSaved }: { row?: Row; readOnly?: boolean; onClose: () => void; onSaved: () => void }) {
  const [refs, setRefs] = useState<{ sections: Row[]; parents: Row[] }>({ sections: [], parents: [] }); const [createParent, setCreateParent] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  useEffect(() => { void Promise.all([api("sections?page=1&page_size=100"), api("users?role=parent&page=1&page_size=100")]).then(([sections, parents]) => setRefs({ sections: rowsFrom(sections), parents: rowsFrom(parents) })).catch((event) => setError(event instanceof Error ? event.message : "Unable to load classes and parents")); }, []);
  async function submit(form: FormData) { if (readOnly) return; setSaving(true); setError(""); try { const fullName = stringValue(form.get("student_name")); const payload: Row = { ...splitName(fullName), date_of_birth: stringValue(form.get("date_of_birth")), gender: stringValue(form.get("gender")), student_id_number: stringValue(form.get("student_id_number")), current_section_id: stringValue(form.get("current_section_id")), admission_number: stringValue(form.get("admission_number")), admission_date: stringValue(form.get("admission_date")) || new Date().toISOString().slice(0, 10), status: "active" }; const saved = await api(row ? `students/${row.id}` : "students", { method: row ? "PUT" : "POST", body: JSON.stringify(payload) }) as Row; const studentId = stringValue(saved.id || row?.id); let parentId = stringValue(form.get("parent_user_id")); if (createParent) { const password = stringValue(form.get("parent_password")); if (password.length < 8) throw new Error("Parent login password must be at least 8 characters."); const parent = await api("users", { method: "POST", body: JSON.stringify({ name: stringValue(form.get("parent_name")), username: stringValue(form.get("parent_username")), password, role: "Parent", email: stringValue(form.get("parent_email")), phone: stringValue(form.get("parent_phone")), is_active: true }) }) as Row; parentId = stringValue(parent.id); }
    if (studentId && parentId) await api(`students/${studentId}/parent`, { method: "PUT", body: JSON.stringify({ parent_user_id: parentId }) }); onSaved(); onClose(); } catch (event) { setError(event instanceof Error ? event.message : "Unable to save student"); } finally { setSaving(false); } }
  const initialName = row ? displayName(row) : "";
  return <Dialog kicker="Student record" title={readOnly ? "Student details" : row ? "Update student" : "Add student"} onClose={onClose}><form action={submit} className="ops-detail-form"><div className="form-grid"><label className="field">Student name<input name="student_name" required readOnly={readOnly} defaultValue={initialName}/></label><label className="field">Class / section<select name="current_section_id" disabled={readOnly} defaultValue={stringValue(row?.current_section_id)} required><option value="">Select section</option>{refs.sections.map((item) => <option key={stringValue(item.id)} value={stringValue(item.id)}>{rowText(item, "grade_name")} · {stringValue(item.section_name ?? item.name)}</option>)}</select></label><label className="field">Student ID<input name="student_id_number" required readOnly={readOnly} defaultValue={stringValue(row?.student_id_number)}/></label><label className="field">Date of birth<input name="date_of_birth" type="date" required readOnly={readOnly} defaultValue={stringValue(row?.date_of_birth).slice(0, 10)}/></label><label className="field">Gender<select name="gender" disabled={readOnly} defaultValue={stringValue(row?.gender) || "male"}><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></label><label className="field">Admission number <small>(optional)</small><input name="admission_number" readOnly={readOnly} defaultValue={stringValue(row?.admission_number)}/></label><label className="field">Admission date<input name="admission_date" type="date" readOnly={readOnly} defaultValue={stringValue(row?.admission_date).slice(0, 10)}/></label><label className="field">Linked parent account<select name="parent_user_id" disabled={readOnly || createParent} defaultValue={stringValue(row?.parent_user_id)}><option value="">Link later</option>{refs.parents.map((item) => <option key={stringValue(item.id)} value={stringValue(item.id)}>{stringValue(item.name) || stringValue(item.username)}{item.username ? ` · ${item.username}` : ""}</option>)}</select></label></div>{!readOnly && !row && <label className="check-field"><input checked={createParent} onChange={(event) => setCreateParent(event.target.checked)} type="checkbox"/> Create parent login with password</label>}{createParent && !readOnly && <div className="parent-login-box"><b>Parent portal account</b><div className="form-grid"><label className="field">Parent name<input name="parent_name" required/></label><label className="field">Parent login username<input name="parent_username" required/></label><label className="field">Parent login password<input name="parent_password" type="password" minLength={8} required/></label><label className="field">Parent email <small>(optional)</small><input name="parent_email" type="email"/></label><label className="field">Parent phone <small>(optional)</small><input name="parent_phone"/></label></div></div>}{error && <p className="form-error">{error}</p>}{readOnly ? <div className="dialog-footer"><button className="secondary-button" type="button" onClick={onClose}>Close</button></div> : <FormActions saving={saving} onClose={onClose} label={row ? "Update student" : "Create student"}/>}</form></Dialog>;
}

function TeacherDialog({ row, readOnly, onClose, onSaved }: { row?: Row; readOnly?: boolean; onClose: () => void; onSaved: () => void }) { const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [designation, setDesignation] = useState(stringValue(row?.designation) || "Teacher");
  async function submit(form: FormData) { if (readOnly) return; setSaving(true); setError(""); try { const payload: Row = { ...splitName(stringValue(form.get("full_name"))), staff_code: stringValue(form.get("staff_code")), username: stringValue(form.get("username")), email: stringValue(form.get("email")), phone: stringValue(form.get("phone")), designation: designation === "Custom" ? stringValue(form.get("custom_designation")) : designation, account_role: stringValue(form.get("account_role")) || "Teacher", gender: "unspecified", request_principal_approval: false }; const password = stringValue(form.get("password")); if (!row && password.length < 8) throw new Error("Temporary password must be at least 8 characters."); if (password) payload.password = password; await api(row ? `staff/${row.id}` : "staff", { method: row ? "PUT" : "POST", body: JSON.stringify(payload) }); onSaved(); onClose(); } catch (event) { setError(event instanceof Error ? event.message : "Unable to save teacher"); } finally { setSaving(false); } }
  return <Dialog kicker="Staff account" title={readOnly ? "Staff details" : row ? "Update staff member" : "Add teacher or coordinator"} onClose={onClose}><form action={submit} className="ops-detail-form"><div className="form-grid"><label className="field">Full name<input name="full_name" required readOnly={readOnly} defaultValue={row ? displayName(row) : ""}/></label><label className="field">Employee ID <small>(optional)</small><input name="staff_code" readOnly={readOnly} defaultValue={stringValue(row?.staff_code)}/></label><label className="field">Designation<select disabled={readOnly} value={designation} onChange={(event) => setDesignation(event.target.value)}><option>Teacher</option><option>Co Teacher</option><option>Coordinator</option><option>Custom</option></select></label>{designation === "Custom" && <label className="field">Custom designation<input name="custom_designation" required readOnly={readOnly} defaultValue={stringValue(row?.designation)}/></label>}<label className="field">Phone <small>(optional)</small><input name="phone" readOnly={readOnly} defaultValue={stringValue(row?.phone)}/></label><label className="field">Email <small>(optional)</small><input name="email" type="email" readOnly={readOnly} defaultValue={stringValue(row?.email)}/></label><label className="field">Login username<input name="username" required readOnly={readOnly} defaultValue={stringValue(row?.username)}/></label>{!row && <label className="field">Login role<select name="account_role" disabled={readOnly} defaultValue="Teacher"><option value="Teacher">Teacher</option><option value="Coordinator">Coordinator</option></select></label>}{!readOnly && <label className="field">{row ? "New password (optional)" : "Temporary password"}<input name="password" type="password" minLength={8} required={!row}/></label>}</div>{error && <p className="form-error">{error}</p>}{readOnly ? <div className="dialog-footer"><button className="secondary-button" type="button" onClick={onClose}>Close</button></div> : <FormActions saving={saving} onClose={onClose} label={row ? "Update staff" : "Create staff account"}/>}</form></Dialog>; }

function GenericDialog({ module, row, readOnly, onClose, onSaved }: { module: Module; row?: Row; readOnly?: boolean; onClose: () => void; onSaved: () => void }) { const [saving, setSaving] = useState(false); const [error, setError] = useState(""); async function submit(form: FormData) { setSaving(true); setError(""); const payload: Row = {}; module.fields.forEach((field) => { const raw = form.get(field.key); payload[field.key] = field.type === "number" ? Number(raw || 0) : raw; }); if (module.id === "parents") { payload.role = "Parent"; payload.is_active = true; } try { await api(row ? `${module.create}/${row.id}` : module.create, { method: row ? "PUT" : "POST", body: JSON.stringify(payload) }); onSaved(); onClose(); } catch (event) { setError(event instanceof Error ? event.message : "Save failed"); } finally { setSaving(false); } } return <Dialog kicker={module.label} title={readOnly ? "Record details" : row ? "Update record" : `Add ${module.label.toLowerCase()}`} onClose={onClose}><form action={submit}>{module.fields.map((field) => <label className="field" key={field.key}>{field.label}{field.type === "textarea" ? <textarea name={field.key} readOnly={readOnly} defaultValue={stringValue(row?.[field.key])}/> : <input required={!readOnly && !["phone", "email", "password"].includes(field.key)} name={field.key} readOnly={readOnly} type={field.type === "number" ? "number" : field.key === "password" ? "password" : "text"} defaultValue={stringValue(row?.[field.key])}/>}</label>)}{error && <p className="form-error">{error}</p>}{readOnly ? <div className="dialog-footer"><button className="secondary-button" type="button" onClick={onClose}>Close</button></div> : <FormActions saving={saving} onClose={onClose}/>}</form></Dialog>; }

function ResourceModule({ module, createToken, onSaved, onNotify }: { module: Module; createToken: number; onSaved: () => void; onNotify: (message: string) => void }) { const [rows, setRows] = useState<Row[]>([]); const [loading, setLoading] = useState(true); const [refreshing, setRefreshing] = useState(false); const [error, setError] = useState(""); const [search, setSearch] = useState(""); const [dialog, setDialog] = useState<{ row?: Row; readOnly?: boolean } | false>(false); const mounted = useRef(true);
  const load = useCallback(async (silent = false) => { if (silent) setRefreshing(true); else setLoading(true); try { const data = await api(module.endpoint); if (mounted.current) { setRows(rowsFrom(data)); setError(""); } } catch (event) { if (mounted.current) setError(event instanceof Error ? event.message : "Unable to load records"); } finally { if (mounted.current) { setLoading(false); setRefreshing(false); } } }, [module.endpoint]); useEffect(() => { mounted.current = true; void load(); return () => { mounted.current = false; }; }, [load]); useEffect(() => { if (createToken) setDialog({}); }, [createToken]); const filtered = useMemo(() => rows.filter((row) => JSON.stringify(row).toLowerCase().includes(search.toLowerCase())), [rows, search]); const afterSave = () => { onNotify("Saved to the SchoolDesk backend. The latest records are now loaded."); void load(true); onSaved(); };
  async function remove(row: Row) { if (!confirm("Remove this record? This follows the existing SchoolDesk backend rules.")) return; try { await api(`${module.create}/${row.id}`, { method: "DELETE" }); afterSave(); } catch (event) { setError(event instanceof Error ? event.message : "Unable to remove record"); } }
  const dialogNode = dialog !== false && (module.id === "students" ? <StudentDialog row={dialog.row} readOnly={dialog.readOnly} onClose={() => setDialog(false)} onSaved={afterSave}/> : module.id === "teachers" ? <TeacherDialog row={dialog.row} readOnly={dialog.readOnly} onClose={() => setDialog(false)} onSaved={afterSave}/> : <GenericDialog module={module} row={dialog.row} readOnly={dialog.readOnly} onClose={() => setDialog(false)} onSaved={afterSave}/>);
  return <section className="ops-module"><div className="ops-module-heading"><div><div className={`ops-module-icon ${module.tone}`}><module.icon size={20}/></div><div><p className="ops-kicker">Live SchoolDesk module</p><h2>{module.label}</h2><p>{module.description}</p></div></div><div className="ops-actions"><button className="secondary-button" onClick={() => void load(true)} disabled={refreshing}>{refreshing ? <LoaderCircle className="spin" size={16}/> : <RefreshCw size={16}/>} Refresh</button><button className="primary-button" onClick={() => setDialog({})}><Plus size={16}/> Add</button></div></div><section className="surface ops-table-surface"><div className="toolbar ops-toolbar"><label className="ops-search"><span className="sr-only">Search current records</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={`Search ${module.label.toLowerCase()}`}/></label><span className="ops-count"><b>{filtered.length}</b> live records</span></div>{error && <div className="ops-inline-error"><CircleAlert size={16}/>{error}</div>}<table className="data-table"><thead><tr>{module.columns.map(([, label]) => <th key={label}>{label}</th>)}<th><span className="sr-only">Actions</span></th></tr></thead><tbody>{loading ? <tr><td colSpan={module.columns.length + 1} className="empty-row"><LoaderCircle className="spin" size={18}/> Loading current SchoolDesk data…</td></tr> : filtered.length ? filtered.map((row) => <tr key={stringValue(row.id)}>{module.columns.map(([key]) => <td key={key}>{key === "status" ? <span className="status-pill">{rowText(row, key)}</span> : rowText(row, key)}</td>)}<td><div className="row-actions"><button className="icon-button" title="View record" onClick={() => setDialog({ row, readOnly: true })}><Eye size={15}/></button><button className="icon-button" title="Edit record" onClick={() => setDialog({ row })}><Pencil size={15}/></button>{module.id === "students" && <button className="icon-button" title="Edit parent link" onClick={() => setDialog({ row })}><Link2 size={15}/></button>}<button className="icon-button danger" title="Remove record" onClick={() => void remove(row)}><Trash2 size={15}/></button></div></td></tr>) : <tr><td colSpan={module.columns.length + 1} className="empty-row">No records match this search.</td></tr>}</tbody></table></section>{dialogNode}</section>; }

function FeeStructureDialog({ refs, onClose, onSaved }: { refs: FeeState; onClose: () => void; onSaved: () => void }) { const [saving, setSaving] = useState(false); const [error, setError] = useState(""); async function submit(form: FormData) { setSaving(true); setError(""); try { const payload = { academic_year_id: stringValue(form.get("academic_year_id")), grade_id: stringValue(form.get("grade_id")), section_id: stringValue(form.get("section_id")) || undefined, fee_category_id: stringValue(form.get("fee_category_id")), amount: Number(form.get("amount")), frequency: stringValue(form.get("frequency")), due_day: Number(form.get("due_day")), late_fine_per_day: Number(form.get("late_fine_per_day") || 0), replace_existing: Boolean(form.get("replace_existing")) }; if (!payload.academic_year_id || !payload.grade_id || !payload.fee_category_id || payload.amount <= 0) throw new Error("Academic year, class, fee category, and a positive amount are required."); const created = await api("fees/structures", { method: "POST", body: JSON.stringify(payload) }) as Row; if (created.id) await api(`fees/structures/${created.id}/invoice-sync/apply`, { method: "POST", body: JSON.stringify({ include_partially_paid: false }) }); onSaved(); onClose(); } catch (event) { setError(event instanceof Error ? event.message : "Unable to save fee structure"); } finally { setSaving(false); } } return <Dialog kicker="Principal finance" title="Create fee structure" onClose={onClose}><form action={submit} className="ops-detail-form"><div className="form-grid"><label className="field">Academic year<select name="academic_year_id" required><option value="">Select academic year</option>{refs.years.map((row) => <option key={stringValue(row.id)} value={stringValue(row.id)}>{stringValue(row.year_name ?? row.name ?? row.label)}</option>)}</select></label><label className="field">Class<select name="grade_id" required><option value="">Select class</option>{refs.grades.map((row) => <option key={stringValue(row.id)} value={stringValue(row.id)}>{stringValue(row.grade_name ?? row.name)}</option>)}</select></label><label className="field">Section <small>(optional)</small><select name="section_id"><option value="">All sections</option>{refs.sections.map((row) => <option key={stringValue(row.id)} value={stringValue(row.id)}>{rowText(row, "grade_name")} · {stringValue(row.section_name ?? row.name)}</option>)}</select></label><label className="field">Fee category<select name="fee_category_id" required><option value="">Select fee category</option>{refs.categories.map((row) => <option key={stringValue(row.id)} value={stringValue(row.id)}>{stringValue(row.category_name ?? row.name)}</option>)}</select></label><label className="field">Frequency<select name="frequency" defaultValue="term"><option value="one_time">One time</option><option value="yearly">Yearly</option><option value="monthly">Monthly</option><option value="term">Term</option></select></label><label className="field">Amount<input name="amount" type="number" min="1" step="0.01" required/></label><label className="field">Due day<input name="due_day" type="number" min="1" max="31" defaultValue="10" required/></label><label className="field">Late fine / day<input name="late_fine_per_day" type="number" min="0" step="0.01" defaultValue="0"/></label></div><label className="check-field"><input name="replace_existing" type="checkbox"/> Replace the matching structure after reviewing its invoices</label>{error && <p className="form-error">{error}</p>}<FormActions saving={saving} onClose={onClose} label="Create and sync invoices"/></form></Dialog>; }

function PaymentDialog({ invoices, onClose, onSaved }: { invoices: Row[]; onClose: () => void; onSaved: () => void }) { const [saving, setSaving] = useState(false); const [error, setError] = useState(""); async function submit(form: FormData) { setSaving(true); setError(""); try { const payload = { invoice_id: stringValue(form.get("invoice_id")), receipt_number: stringValue(form.get("receipt_number")), amount_paid: Number(form.get("amount_paid")), payment_date: stringValue(form.get("payment_date")), payment_mode: stringValue(form.get("payment_mode")), transaction_id: stringValue(form.get("transaction_id")) || undefined }; if (!payload.invoice_id || payload.amount_paid <= 0 || !payload.receipt_number) throw new Error("Invoice, receipt number, and a positive payment amount are required."); await api("fees/payments", { method: "POST", body: JSON.stringify(payload) }); onSaved(); onClose(); } catch (event) { setError(event instanceof Error ? event.message : "Unable to record payment"); } finally { setSaving(false); } } return <Dialog kicker="Collections" title="Record verified payment" onClose={onClose}><form action={submit} className="ops-detail-form"><label className="field">Outstanding invoice<select name="invoice_id" required><option value="">Select invoice</option>{invoices.filter((row) => Number(row.balance ?? row.amount ?? 0) > 0).map((row) => <option key={stringValue(row.id)} value={stringValue(row.id)}>{displayName(nested(row, "student"))} · {stringValue(row.invoice_number ?? row.id)} · {money(row.balance ?? row.amount)}</option>)}</select></label><div className="form-grid"><label className="field">Receipt number<input name="receipt_number" defaultValue={`RCP${Date.now()}`} required/></label><label className="field">Amount<input name="amount_paid" type="number" min="1" step="0.01" required/></label><label className="field">Payment date<input name="payment_date" type="date" defaultValue={new Date().toISOString().slice(0, 10)} required/></label><label className="field">Payment mode<select name="payment_mode" defaultValue="cash"><option value="cash">Cash</option><option value="online">Online</option><option value="cheque">Cheque</option><option value="dd">DD</option></select></label><label className="field">Transaction ID <small>(optional for cash)</small><input name="transaction_id"/></label></div>{error && <p className="form-error">{error}</p>}<FormActions saving={saving} onClose={onClose} label="Record payment"/></form></Dialog>; }

function ConcessionDialog({ invoices, onClose, onSaved }: { invoices: Row[]; onClose: () => void; onSaved: () => void }) { const [saving, setSaving] = useState(false); const [kind, setKind] = useState("amount"); const [error, setError] = useState(""); async function submit(form: FormData) { setSaving(true); setError(""); try { const raw = Number(form.get("value")); const payload: Row = { invoice_id: stringValue(form.get("invoice_id")), reason: stringValue(form.get("reason")), [kind]: raw }; if (!payload.invoice_id || !payload.reason || raw <= 0) throw new Error("Invoice, reason, and a positive concession value are required."); await api("fees/concessions", { method: "POST", body: JSON.stringify(payload) }); onSaved(); onClose(); } catch (event) { setError(event instanceof Error ? event.message : "Unable to apply concession"); } finally { setSaving(false); } } return <Dialog kicker="Principal finance" title="Apply fee concession" onClose={onClose}><form action={submit} className="ops-detail-form"><label className="field">Invoice<select name="invoice_id" required><option value="">Select invoice</option>{invoices.filter((row) => Number(row.balance ?? 0) > 0).map((row) => <option key={stringValue(row.id)} value={stringValue(row.id)}>{displayName(nested(row, "student"))} · {stringValue(row.invoice_number ?? row.id)} · {money(row.balance)}</option>)}</select></label><div className="form-grid"><label className="field">Concession type<select value={kind} onChange={(event) => setKind(event.target.value)}><option value="amount">Amount (INR)</option><option value="percentage">Percentage</option></select></label><label className="field">{kind === "amount" ? "Amount" : "Percentage"}<input name="value" type="number" min="0.01" max={kind === "percentage" ? "100" : undefined} step="0.01" required/></label></div><label className="field">Reason<textarea name="reason" required/></label>{error && <p className="form-error">{error}</p>}<FormActions saving={saving} onClose={onClose} label="Apply concession"/></form></Dialog>; }

function FinanceTable({ rows, columns, empty }: { rows: Row[]; columns: Array<[string, string]>; empty: string }) { return <section className="surface ops-table-surface"><table className="data-table"><thead><tr>{columns.map(([, label]) => <th key={label}>{label}</th>)}</tr></thead><tbody>{rows.length ? rows.slice(0, 50).map((row) => <tr key={stringValue(row.id)}>{columns.map(([key]) => <td key={key}>{key === "amount" || key === "balance" || key === "total_amount" ? money(row[key]) : key === "student" ? displayName(nested(row, "student")) : rowText(row, key)}</td>)}</tr>) : <tr><td colSpan={columns.length} className="empty-row">{empty}</td></tr>}</tbody></table></section>; }

function FeesWorkspace({ onNotify }: { onNotify: (message: string) => void }) { const [state, setState] = useState<FeeState>(emptyFees); const [tab, setTab] = useState("structures"); const [loading, setLoading] = useState(true); const [notice, setNotice] = useState(""); const [dialog, setDialog] = useState<"structure" | "payment" | "concession" | false>(false);
  const load = useCallback(async () => { setLoading(true); try { const [structures, invoices, payments, requests, concessions, categories, years, grades, sections, config] = await Promise.all([api("fees/structures"), api("fees/invoices?page=1&page_size=100"), api("fees/payments?page=1&page_size=100"), api("fees/payment-requests"), api("fees/concessions"), api("fees/categories"), api("academic-years"), api("grades"), api("sections?page=1&page_size=100"), api("fees/payment-config")]); setState({ structures: rowsFrom(structures), invoices: rowsFrom(invoices), payments: rowsFrom(payments), requests: rowsFrom(requests), concessions: rowsFrom(concessions), categories: rowsFrom(categories), years: rowsFrom(years), grades: rowsFrom(grades), sections: rowsFrom(sections), config: (config && typeof config === "object" ? config : {}) as Row }); setNotice(""); } catch (event) { setNotice(event instanceof Error ? event.message : "Unable to load finance workspace"); } finally { setLoading(false); } }, []); useEffect(() => { void load(); }, [load]); const saved = () => { onNotify("Finance record saved and all live fee lists refreshed."); void load(); };
  async function applyFines() { try { await api("fees/invoices/late-fines/apply", { method: "POST", body: JSON.stringify({}) }); onNotify("Late fine check completed. The invoice list is refreshed."); void load(); } catch (event) { setNotice(event instanceof Error ? event.message : "Unable to apply late fines"); } }
  async function decide(request: Row, status: "approved" | "rejected") { if (!confirm(`${status === "approved" ? "Approve" : "Reject"} this parent payment request?`)) return; try { await api(`fees/payment-requests/${request.id}/decision`, { method: "PUT", body: JSON.stringify({ status }) }); onNotify(`Payment request ${status}. Finance data is refreshed.`); void load(); } catch (event) { setNotice(event instanceof Error ? event.message : "Unable to update payment request"); } }
  async function saveConfig(form: FormData) { try { await api("fees/payment-config", { method: "PUT", body: JSON.stringify({ upi_id: stringValue(form.get("upi_id")), payee_name: stringValue(form.get("payee_name")), merchant_code: stringValue(form.get("merchant_code")), qr_note: stringValue(form.get("qr_note")), upi_enabled: form.get("upi_enabled") === "on" }) }); onNotify("Payment configuration saved to SchoolDesk."); void load(); } catch (event) { setNotice(event instanceof Error ? event.message : "Unable to save payment configuration"); } }
  const tabs = [["structures", "Structures"], ["invoices", "Invoices"], ["collections", "Collections"], ["requests", "Payment requests"], ["concessions", "Concessions"], ["reports", "Reports & setup"]] as const;
  return <section className="ops-module"><div className="ops-module-heading"><div><div className="ops-module-icon gold"><WalletCards size={20}/></div><div><p className="ops-kicker">Principal-only finance</p><h2>Fees workspace</h2><p>Structures, invoices, collections, concessions, parent requests, and payment configuration from the mobile finance backend.</p></div></div><div className="ops-actions"><button className="secondary-button" onClick={() => void load()}><RefreshCw size={16}/> Refresh</button><button className="primary-button" onClick={() => setDialog("structure")}><Plus size={16}/> Fee structure</button></div></div><div className="finance-summary"><article><small>Fee structures</small><b>{state.structures.length}</b></article><article><small>Outstanding invoices</small><b>{state.invoices.filter((row) => Number(row.balance ?? 0) > 0).length}</b></article><article><small>Collected payments</small><b>{state.payments.length}</b></article><article><small>Pending requests</small><b>{state.requests.filter((row) => stringValue(row.status).toLowerCase() === "pending").length}</b></article></div><div className="finance-tabs" role="tablist" aria-label="Finance views">{tabs.map(([id, label]) => <button role="tab" aria-selected={tab === id} className={tab === id ? "active" : ""} key={id} onClick={() => setTab(id)}>{label}</button>)}</div>{notice && <div className="ops-inline-error"><CircleAlert size={16}/>{notice}</div>}{loading ? <p className="loading">Loading live finance records…</p> : <div className="finance-tab-content">{tab === "structures" && <><div className="finance-actions"><button className="primary-button" onClick={() => setDialog("structure")}><Plus size={16}/> Create structure</button><button className="secondary-button" onClick={() => void applyFines()}>Apply late-fine check</button></div><FinanceTable rows={state.structures} columns={[["category_name", "Category"], ["frequency", "Frequency"], ["amount", "Amount"], ["due_day", "Due day"]]} empty="No fee structures yet."/></>}{tab === "invoices" && <FinanceTable rows={state.invoices} columns={[["invoice_number", "Invoice"], ["student", "Student"], ["total_amount", "Total"], ["balance", "Balance"], ["status", "Status"]]} empty="No invoices yet."/>}{tab === "collections" && <><div className="finance-actions"><button className="primary-button" onClick={() => setDialog("payment")}><ReceiptIndianRupee size={16}/> Record payment</button></div><FinanceTable rows={state.payments} columns={[["receipt_number", "Receipt"], ["student", "Student"], ["amount", "Amount"], ["payment_method", "Mode"], ["paid_at", "Paid at"]]} empty="No payment collections yet."/></>}{tab === "requests" && <section className="surface request-list">{state.requests.length ? state.requests.map((request) => <article key={stringValue(request.id)}><div><b>{displayName(nested(request, "student")) || stringValue(request.student_name) || "Parent payment request"}</b><span>{money(request.amount)} · {stringValue(request.payment_method || "UPI")} · {stringValue(request.status || "pending")}</span></div>{stringValue(request.status).toLowerCase() === "pending" && <div><button className="outline-button" onClick={() => void decide(request, "rejected")}>Reject</button><button className="primary-button" onClick={() => void decide(request, "approved")}>Approve</button></div>}</article>) : <p className="empty-row">No parent payment requests yet.</p>}</section>}{tab === "concessions" && <><div className="finance-actions"><button className="primary-button" onClick={() => setDialog("concession")}><Plus size={16}/> Apply concession</button></div><FinanceTable rows={state.concessions} columns={[["student_name", "Student"], ["fee_item_name", "Fee item"], ["amount", "Amount"], ["percentage", "Percentage"], ["status", "Status"]]} empty="No concessions have been applied."/></>}{tab === "reports" && <div className="finance-report-grid"><section className="surface finance-report-card"><FileText size={22}/><h3>Live finance snapshot</h3><p>{state.invoices.filter((row) => Number(row.balance ?? 0) > 0).length} invoices have an outstanding balance. Use the invoice and collection tabs to review the canonical records before exporting a report.</p><button className="secondary-button" onClick={() => window.print()}>Print this summary</button></section><section className="surface ops-form-surface"><h3>UPI payment configuration</h3><p>Matches the mobile payment-configuration contract and is visible only to the Principal.</p><form action={saveConfig}><label className="field">UPI ID<input name="upi_id" defaultValue={stringValue(state.config.upi_id)}/></label><label className="field">Payee name<input name="payee_name" defaultValue={stringValue(state.config.payee_name)}/></label><label className="field">Merchant code <small>(optional)</small><input name="merchant_code" defaultValue={stringValue(state.config.merchant_code)}/></label><label className="field">QR note <small>(optional)</small><input name="qr_note" defaultValue={stringValue(state.config.qr_note)}/></label><label className="check-field"><input name="upi_enabled" type="checkbox" defaultChecked={state.config.upi_enabled !== false}/> Enable UPI payments</label><button className="primary-button">Save payment setup</button></form></section></div>}</div>}{dialog === "structure" && <FeeStructureDialog refs={state} onClose={() => setDialog(false)} onSaved={saved}/>} {dialog === "payment" && <PaymentDialog invoices={state.invoices} onClose={() => setDialog(false)} onSaved={saved}/>} {dialog === "concession" && <ConcessionDialog invoices={state.invoices} onClose={() => setDialog(false)} onSaved={saved}/>}</section>; }

function DashboardPanel({ role, onNavigate, onCreate, refreshNonce }: { role: PortalRole; onNavigate: (module: string) => void; onCreate: (module: string) => void; refreshNonce: number }) { const [data, setData] = useState<Dashboard>({}); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [refreshedAt, setRefreshedAt] = useState<Date | null>(null); const load = useCallback(async () => { setLoading(true); try { const live = await api("dashboard"); setData(live as Dashboard); setError(""); setRefreshedAt(new Date()); } catch (event) { setError(event instanceof Error ? event.message : "Unable to load the operations snapshot"); } finally { setLoading(false); } }, []); useEffect(() => { void load(); }, [load, refreshNonce]); useEffect(() => { const timer = window.setInterval(() => void load(), 60000); return () => window.clearInterval(timer); }, [load]); const metrics = [{ key: "students", label: "Students", value: data.total_students ?? 0, note: "Live learner records", icon: UsersRound, tone: "blue" }, { key: "teachers", label: "Teachers", value: data.total_staff ?? 0, note: "Active staff directory", icon: GraduationCap, tone: "green" }, { key: "classes", label: "Classes", value: data.total_sections ?? 0, note: "Configured sections", icon: Building2, tone: "violet" }, { key: "attendance", label: "Today’s attendance", value: `${data.today_attendance?.attendance_pct ?? 0}%`, note: `${data.today_attendance?.present ?? 0} present of ${data.today_attendance?.marked ?? 0} marked`, icon: CheckCircle2, tone: "teal" }]; return <section className="ops-dashboard"><div className="ops-dashboard-heading"><div><p className="ops-kicker">{role === "principal" ? "School command center" : "School operations center"}</p><h2>Good to see you.</h2><p>Everything shown here is loaded from the same SchoolDesk backend used by the app.</p></div><div className="ops-live"><span><i/> Live sync</span><small>{refreshedAt ? `Updated ${refreshedAt.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}` : "Connecting…"}</small></div></div>{error && <div className="ops-inline-error"><CircleAlert size={16}/>{error}<button onClick={() => void load()}>Retry</button></div>}<div className="ops-metric-grid">{metrics.map((metric) => <button className={`ops-metric-card ${metric.tone}`} key={metric.key} onClick={() => onNavigate(metric.key === "attendance" ? "timetable" : metric.key)}><span className="ops-metric-icon"><metric.icon size={21}/></span><span><small>{metric.label}</small><b>{loading ? "—" : metric.value}</b><em>{metric.note}</em></span><ArrowRight size={16}/></button>)}</div><div className="ops-dashboard-grid"><section className="ops-panel ops-health-panel"><div className="ops-panel-heading"><div><span className="ops-panel-icon"><Activity size={18}/></span><div><h3>Today’s operating picture</h3><p>Live school signals, refreshed every minute.</p></div></div><button className="text-button" onClick={() => void load()}><RefreshCw size={15}/> Refresh</button></div><div className="ops-health-list"><div><span>Attendance marked</span><b>{data.today_attendance?.marked ?? 0} records</b><progress value={Math.min(data.today_attendance?.attendance_pct ?? 0, 100)} max="100"/></div><div><span>Pending leave requests</span><b>{data.pending_leave_requests ?? 0}</b><span className="ops-subtle">Review staff availability</span></div>{role === "principal" && <div><span>Fee collection</span><b>{data.fees?.collection_pct ?? 0}%</b><span className="ops-subtle">{money(data.fees?.total_paid)} collected</span></div>}</div><div className="ops-quick-actions"><button onClick={() => onCreate("students")}><Plus size={17}/><span>Add student</span></button><button onClick={() => onNavigate("teachers")}><GraduationCap size={17}/><span>Manage teachers</span></button><button onClick={() => onNavigate("timetable")}><CalendarClock size={17}/><span>Open timetable</span></button>{role === "principal" && <button onClick={() => onNavigate("fees")}><WalletCards size={17}/><span>Fees workspace</span></button>}</div></section><section className="ops-panel ops-activity-panel"><div className="ops-panel-heading"><div><span className="ops-panel-icon gold"><ShieldCheck size={18}/></span><div><h3>Attention queue</h3><p>Prioritise what needs a look.</p></div></div></div><div className="ops-task-list">{[{ label: "Pending leave requests", value: data.pending_leave_requests ?? 0, target: "teachers" }, { label: "Access and approval requests", value: data.metrics?.pending_access_approvals ?? 0, target: "students" }, { label: "Timetable slots", value: "Open", target: "timetable" }].map((task) => <button key={task.label} onClick={() => onNavigate(task.target)}><span className={task.value === 0 ? "task-check" : "task-warn"}>{task.value === 0 ? <CheckCircle2 size={16}/> : <CircleAlert size={16}/>}</span><span><b>{task.label}</b><small>{task.value === 0 ? "All clear" : typeof task.value === "number" ? `${task.value} awaiting attention` : "Open workspace"}</small></span><ChevronRight size={17}/></button>)}</div></section></div></section>; }

function WebsiteManager({ onNotify }: { onNotify: (message: string) => void }) { const [content, setContent] = useState<Row>({}); const [gallery, setGallery] = useState<Row[]>([]); const [notice, setNotice] = useState(""); const [loading, setLoading] = useState(true); const load = useCallback(async () => { setLoading(true); try { const [website, images] = await Promise.all([api("website/content"), api("website/gallery")]); setContent(website as Row); setGallery(rowsFrom(images)); setNotice(""); } catch (event) { setNotice(event instanceof Error ? event.message : "Unable to load website content"); } finally { setLoading(false); } }, []); useEffect(() => { void load(); }, [load]); async function saveContent(form: FormData) { try { await api("website/content", { method: "PUT", body: JSON.stringify(Object.fromEntries(form)) }); onNotify("Public website copy published. Visitors will see the update shortly."); void load(); } catch (event) { setNotice(event instanceof Error ? event.message : "Unable to save"); } } async function upload(form: FormData) { try { await api("website/gallery/upload", { method: "POST", body: form }); onNotify("Gallery image uploaded as a draft."); void load(); } catch (event) { setNotice(event instanceof Error ? event.message : "Upload failed"); } } async function toggle(row: Row) { try { await api(`website/gallery/${row.id}`, { method: "PUT", body: JSON.stringify({ ...row, is_published: !row.is_published }) }); onNotify(row.is_published ? "Gallery item unpublished." : "Gallery item is now public."); void load(); } catch (event) { setNotice(event instanceof Error ? event.message : "Unable to update gallery"); } } return <section className="ops-module"><div className="ops-module-heading"><div><div className="ops-module-icon green"><Globe2 size={20}/></div><div><p className="ops-kicker">Principal-only publishing</p><h2>Public Website</h2><p>Update the ArishVille story and curate photos without exposing operational school media.</p></div></div><div className="ops-actions"><button className="secondary-button" onClick={() => void load()}><RefreshCw size={16}/> Refresh</button></div></div>{notice && <div className="ops-inline-error"><CircleAlert size={16}/>{notice}</div>}<div className="website-grid ops-website-grid"><section className="surface ops-form-surface"><h3>Homepage copy</h3><p>These changes revalidate the public website after a successful save.</p><form action={saveContent}><label className="field">Hero title<input name="hero_title" required defaultValue={stringValue(content.hero_title)}/></label><label className="field">Hero description<textarea name="hero_body" required defaultValue={stringValue(content.hero_body)}/></label><label className="field">Mission title<input name="mission_title" required defaultValue={stringValue(content.mission_title)}/></label><label className="field">Mission statement<textarea name="mission_body" required defaultValue={stringValue(content.mission_body)}/></label><button className="primary-button">Publish website copy</button></form></section><section className="surface ops-form-surface"><h3>Curated gallery</h3><p>Upload only photos cleared for the public ArishVille website.</p><form action={upload}><label className="field">Photo<input name="file" type="file" accept="image/jpeg,image/png,image/webp" required/></label><label className="field">Title<input name="title"/></label><label className="field">Accessible description<input name="alt_text" required/></label><label className="field">Caption<input name="caption"/></label><button className="secondary-button">Upload as draft</button></form><div className="ops-gallery-list">{loading ? <p className="loading">Loading gallery…</p> : gallery.length ? gallery.map((row) => <div className="gallery-admin-item" key={stringValue(row.id)}><img className="gallery-thumb" src={stringValue(row.media_url)} alt=""/><div><b>{stringValue(row.title) || "Untitled image"}</b><small>{row.is_published ? "Published" : "Draft"}</small></div><button className="outline-button" onClick={() => void toggle(row)}>{row.is_published ? "Unpublish" : "Publish"}</button></div>) : <p className="ops-empty-small">No public gallery images yet.</p>}</div></section></div></section>; }

export function PortalClient({ role }: { role: PortalRole }) { const [active, setActive] = useState("overview"); const [createToken, setCreateToken] = useState(0); const [dashboardRefresh, setDashboardRefresh] = useState(0); const [toast, setToast] = useState(""); const nav = visibleModules(role); const selected = modules.find((item) => item.id === active); const navigate = (target: string) => { if (!(nav as readonly string[]).includes(target)) return; setActive(target); setCreateToken(0); }; const createInModule = (target: string) => { if (!(nav as readonly string[]).includes(target)) return; setActive(target); setCreateToken(Date.now()); }; const notify = useCallback((message: string) => setToast(message), []); async function logout() { await fetch("/api/auth/logout", { method: "POST" }); location.assign("/"); } return <main className="portal ops-portal"><aside className="sidebar ops-sidebar"><a href="/" className="portal-brand"><img src="/branding/arishville-logo.png" alt="ArishVille Preschool"/><span>ArishVille<small>Preschool</small></span></a><p className="ops-role-chip"><ShieldCheck size={14}/>{role === "principal" ? "Principal workspace" : "Coordinator workspace"}</p><nav className="side-nav" aria-label="Portal navigation">{nav.map((id) => { const meta = navMeta[id]; const Icon = meta.icon; return <button key={id} onClick={() => { setActive(id); setCreateToken(0); }} className={active === id ? "active" : ""}><Icon size={17}/><span>{meta.label}</span></button>; })}</nav>{role === "coordinator" && <p className="finance-note"><WalletCards size={15}/> Finance is safely managed by the Principal.</p>}<div className="ops-sidebar-status"><i/><span>SchoolDesk connected</span></div></aside><div className="portal-main"><header className="portal-topbar ops-topbar"><div><p>{role === "principal" ? "Principal Portal" : "Coordinator Portal"}</p><h1>{active === "overview" ? "Operations overview" : navMeta[active]?.label}</h1></div><div className="ops-topbar-actions"><button className="secondary-button" onClick={() => setDashboardRefresh((value) => value + 1)}><RefreshCw size={16}/> Refresh data</button><button className="secondary-button" onClick={() => void logout()}>Sign out</button></div></header><section className="portal-content ops-content">{active === "overview" ? <DashboardPanel role={role} onNavigate={navigate} onCreate={createInModule} refreshNonce={dashboardRefresh}/> : active === "website" && role === "principal" ? <WebsiteManager onNotify={notify}/> : active === "fees" && role === "principal" ? <FeesWorkspace onNotify={notify}/> : selected ? <ResourceModule module={selected} createToken={createToken} onSaved={() => setDashboardRefresh((value) => value + 1)} onNotify={notify}/> : null}</section></div>{toast && <Toast message={toast} onClose={() => setToast("")}/>}</main>; }
